static void btree_gc_merge_node(struct btree *b, struct btree_op *op,
				struct gc_merge_info *i, struct gc_stat *gc)
{
	struct btree_iter iter;
	struct bkey *k;

	bch_btree_iter_init(&b->keys, &iter, NULL);

	while ((k = bch_btree_iter_next(&iter))) {
		if (bch_ptr_bad(k))
			continue;

		if (bch_btree_node_get(b->c, op, k, b->level - 1, true, b))
			continue;

		if (btree_gc_mark_node(i->b, gc))
			btree_gc_rewrite_node(b, op, i->b);

		if (i->b->level)
			btree_gc_recurse(b, op, &gc->writes, gc);

		bkey_copy_key(&b->c->gc_done, &i->b->key);

		mutex_lock(&i->b->write_lock);
		if (btree_node_dirty(i->b))
			bch_btree_node_write(i->b, &gc->writes);
		mutex_unlock(&i->b->write_lock);
		rw_unlock(true, i->b);

		i->b = ERR_PTR(-EINTR);
	}
}
